/// <summary>
/// PricingAttribute of table <c>InventDim</c> field InventColorId.
/// </summary>
/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventDimInventColorId extends UPSPricingAttributeInventDim implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, InventColorId);
}

public Set getAllowedValues()
{
    var       ret = new Set(Types::String);
    InventDim inventDim;

    while select inventDim
        group by InventColorId
    {
        if (! ret.in(inventDim.InventColorId))
        {
            ret.add(inventDim.InventColorId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, InventColorId));
    qbr.value(queryValue(_value));
}
